#[derive(Debug, Default, Clone)]
struct RunMetrics {
    workflow_stage_steps: usize,
    llm_invocations: usize,
    llm_runtime_ms: u64,
    prompt_tokens: usize,
    generated_tokens: usize,
    tool_calls: usize,
    tool_runtime_ms: u64,
    llm_energy_joules: f64,
    llm_energy_kwh: f64,
    tool_energy_joules: f64,
    tool_energy_kwh: f64,
    cache_persistence_queued_checkpoints: usize,
    cache_persistence_completed_checkpoints: usize,
    cache_persistence_wall_ms: u64,
    cache_persistence_failures: usize,
    pending_read_cache_hits: usize,
}

impl RunMetrics {
    fn add(&mut self, other: &RunMetrics) {
        self.workflow_stage_steps = self
            .workflow_stage_steps
            .saturating_add(other.workflow_stage_steps);
        self.llm_invocations = self.llm_invocations.saturating_add(other.llm_invocations);
        self.llm_runtime_ms = self.llm_runtime_ms.saturating_add(other.llm_runtime_ms);
        self.prompt_tokens = self.prompt_tokens.saturating_add(other.prompt_tokens);
        self.generated_tokens = self.generated_tokens.saturating_add(other.generated_tokens);
        self.tool_calls = self.tool_calls.saturating_add(other.tool_calls);
        self.tool_runtime_ms = self.tool_runtime_ms.saturating_add(other.tool_runtime_ms);
        self.llm_energy_joules += other.llm_energy_joules;
        self.llm_energy_kwh += other.llm_energy_kwh;
        self.tool_energy_joules += other.tool_energy_joules;
        self.tool_energy_kwh += other.tool_energy_kwh;
        self.cache_persistence_queued_checkpoints = self
            .cache_persistence_queued_checkpoints
            .saturating_add(other.cache_persistence_queued_checkpoints);
        self.cache_persistence_completed_checkpoints = self
            .cache_persistence_completed_checkpoints
            .saturating_add(other.cache_persistence_completed_checkpoints);
        self.cache_persistence_wall_ms = self
            .cache_persistence_wall_ms
            .saturating_add(other.cache_persistence_wall_ms);
        self.cache_persistence_failures = self
            .cache_persistence_failures
            .saturating_add(other.cache_persistence_failures);
    }
}

#[derive(Debug, Clone, Copy)]
struct RunBudgetLimits {
    advisory_calls: usize,
    model_invocations: usize,
    generated_tokens: usize,
}

impl Default for RunBudgetLimits {
    fn default() -> Self {
        Self {
            advisory_calls: MAX_ADVISORY_CALLS_PER_RUN,
            model_invocations: MAX_MODEL_INVOCATIONS_PER_RUN,
            generated_tokens: MAX_GENERATED_TOKENS_PER_RUN,
        }
    }
}

#[derive(Debug)]
struct RunBudget {
    limits: RunBudgetLimits,
    advisory_calls: usize,
    model_invocations: usize,
    generated_tokens: usize,
}

impl Default for RunBudget {
    fn default() -> Self {
        Self::new(RunBudgetLimits::default())
    }
}

impl RunBudget {
    const fn new(limits: RunBudgetLimits) -> Self {
        Self {
            limits,
            advisory_calls: 0,
            model_invocations: 0,
            generated_tokens: 0,
        }
    }

    fn reserve_advisory_call(&mut self) -> Result<()> {
        if self.advisory_calls >= self.limits.advisory_calls {
            bail!(
                "advisory call limit reached ({})",
                self.limits.advisory_calls
            );
        }
        self.advisory_calls = self.advisory_calls.saturating_add(1);
        Ok(())
    }

    fn next_model_max_tokens(&self, requested_max_tokens: i32) -> Result<i32> {
        if self.model_invocations >= self.limits.model_invocations {
            bail!(
                "model invocation limit reached ({})",
                self.limits.model_invocations
            );
        }
        if self.generated_tokens >= self.limits.generated_tokens {
            bail!(
                "generated token limit reached ({})",
                self.limits.generated_tokens
            );
        }

        let remaining_tokens = self
            .limits
            .generated_tokens
            .saturating_sub(self.generated_tokens)
            .min(i32::MAX as usize) as i32;
        let max_tokens = requested_max_tokens.max(1).min(remaining_tokens.max(1));
        Ok(max_tokens)
    }

    fn reserve_model_invocation(&mut self, requested_max_tokens: i32) -> Result<i32> {
        let max_tokens = self.next_model_max_tokens(requested_max_tokens)?;
        self.model_invocations = self.model_invocations.saturating_add(1);
        Ok(max_tokens)
    }

    fn record_generated_tokens(&mut self, generated_tokens: usize) {
        self.generated_tokens = self.generated_tokens.saturating_add(generated_tokens);
    }

    fn for_workflow(limits: crate::workflow::WorkflowLimits) -> Self {
        Self::new(RunBudgetLimits {
            advisory_calls: limits.advisory_calls,
            model_invocations: limits.total_model_invocations,
            generated_tokens: limits.total_generated_tokens,
        })
    }
}

