fn builtin_tool(
    name: &'static str,
    description: &'static str,
    input_schema: Value,
) -> BuiltInToolSchema {
    BuiltInToolSchema {
        name: name.to_string(),
        description: description.to_string(),
        input_schema,
    }
}

fn object_schema<const P: usize, const R: usize>(
    properties: [(&'static str, Value); P],
    required: [&'static str; R],
) -> Value {
    let mut property_map = Map::new();
    for (name, schema) in properties {
        property_map.insert(name.to_string(), schema);
    }
    json!({
        "type": "object",
        "properties": property_map,
        "required": required.to_vec(),
        "additionalProperties": false,
    })
}

fn string_property(name: &'static str, description: &'static str) -> (&'static str, Value) {
    (
        name,
        json!({ "type": "string", "description": description }),
    )
}

const NATIVE_ACTION_RESERVE_TOKENS: i32 = 192;
const MUTATION_PAYLOAD_CHARS_PER_TOKEN: usize = 4;

fn mutation_payload_char_limit(max_tokens: i32) -> usize {
    usize::try_from(
        max_tokens
            .saturating_sub(NATIVE_ACTION_RESERVE_TOKENS)
            .max(64),
    )
    .unwrap_or(64)
    .saturating_mul(MUTATION_PAYLOAD_CHARS_PER_TOKEN)
}

fn compact_mutation_retry_max_tokens(current_max_tokens: i32, payload_chars: usize) -> i32 {
    let payload_tokens = payload_chars.div_ceil(MUTATION_PAYLOAD_CHARS_PER_TOKEN);
    let payload_tokens = i32::try_from(payload_tokens).unwrap_or(i32::MAX);
    NATIVE_ACTION_RESERVE_TOKENS
        .saturating_add(payload_tokens)
        .clamp(1, current_max_tokens.max(1))
}

fn apply_mutation_payload_limit(tools: &mut [BuiltInToolSchema], max_tokens: i32) -> usize {
    let limit = mutation_payload_char_limit(max_tokens);
    set_mutation_payload_char_limit(tools, limit);
    for tool in tools {
        if !matches!(
            tool.name.as_str(),
            "write_file" | "replace_file" | "apply_patch" | "edit_file"
        ) {
            continue;
        }
        tool.description.push_str(&format!(
            " This turn permits at most {limit} characters of serialized mutation payload; use a complete smaller work unit when the final file is larger."
        ));
    }
    limit
}

fn set_mutation_payload_char_limit(tools: &mut [BuiltInToolSchema], limit: usize) {
    for tool in tools {
        let fields: &[&str] = match tool.name.as_str() {
            "write_file" | "replace_file" => &["content"],
            "apply_patch" => &["patch"],
            // Both strings share one serialized action, so give each half of the allowance.
            "edit_file" => &["old_text", "new_text"],
            _ => continue,
        };
        let field_limit = if tool.name == "edit_file" {
            (limit / 2).max(64)
        } else {
            limit.max(64)
        };
        for field in fields {
            if let Some(property) = tool
                .input_schema
                .pointer_mut(&format!("/properties/{field}"))
            {
                property["maxLength"] = json!(field_limit);
            }
        }
    }
}

fn set_tool_target_path(tools: &mut [BuiltInToolSchema], tool_name: &str, target_path: &str) {
    for tool in tools {
        if tool.name != tool_name {
            continue;
        }
        if let Some(property) = tool.input_schema.pointer_mut("/properties/path") {
            property["enum"] = json!([target_path]);
        }
    }
}

fn replan_supported_for_work_unit(
    contract_allowed_paths: Option<&[String]>,
    unit: &crate::workflow::WorkUnit,
) -> bool {
    if !matches!(
        unit.state,
        crate::workflow::WorkUnitState::DiagnosticFailed
            | crate::workflow::WorkUnitState::DiagnosticRepairReady
    ) {
        return true;
    }
    !contract_allowed_paths.is_some_and(|allowed_paths| {
        allowed_paths.len() == 1 && allowed_paths.first().is_some_and(|path| path == &unit.path)
    })
}

fn scope_tools_to_work_unit(
    tools: &mut Vec<BuiltInToolSchema>,
    unit: &crate::workflow::WorkUnit,
    replan_supported: bool,
) {
    use crate::workflow::{PlannedChange, WorkUnitState};

    let allowed: &[&str] = match unit.state {
        WorkUnitState::EvidenceNeeded | WorkUnitState::DiagnosticFailed => {
            &["read_file", "request_replan"][..]
        }
        WorkUnitState::DiagnosticRepairReady => {
            &["replace_file", "edit_file", "request_replan"][..]
        }
        WorkUnitState::MutationReady => match unit.operation {
            PlannedChange::Create => &["write_file", "request_replan"],
            PlannedChange::Modify => &["replace_file", "edit_file", "request_replan"],
            PlannedChange::Delete => &["rm", "request_replan"],
        },
        WorkUnitState::BlockedForReplan => &["request_replan"],
        WorkUnitState::StructurallyComplete => &[],
    };
    tools.retain(|tool| allowed.contains(&tool.name.as_str()));
    if !replan_supported {
        tools.retain(|tool| tool.name != "request_replan");
    }
    for tool_name in ["read_file", "write_file", "replace_file", "edit_file", "rm"] {
        if let Some(tool) = tools.iter_mut().find(|tool| tool.name == tool_name)
            && let Some(required) = tool
                .input_schema
                .get_mut("required")
                .and_then(Value::as_array_mut)
        {
            required.retain(|field| field.as_str() != Some("path"));
        }
    }
}

fn prefer_atomic_replace_for_small_python_observation(
    tools: &mut Vec<BuiltInToolSchema>,
    unit: &crate::workflow::WorkUnit,
    receipt: &crate::workflow::ControllerObservationReceipt,
) -> bool {
    if unit.operation != crate::workflow::PlannedChange::Modify
        || unit.state != crate::workflow::WorkUnitState::MutationReady
        || !matches!(
            Path::new(&unit.path)
                .extension()
                .and_then(|value| value.to_str()),
            Some("py" | "pyi")
        )
        || receipt.coverage != crate::workflow::ObservationCoverage::Full
        || receipt.path != unit.path
    {
        return false;
    }
    let Some(replace_limit) = tools
        .iter()
        .find(|tool| tool.name == "replace_file")
        .and_then(|tool| {
            tool.input_schema
                .pointer("/properties/content/maxLength")
                .and_then(Value::as_u64)
        })
        .and_then(|limit| usize::try_from(limit).ok())
    else {
        return false;
    };
    if receipt.observed_bytes.saturating_mul(2) > replace_limit {
        return false;
    }
    tools.retain(|tool| tool.name != "edit_file");
    if let Some(replace) = tools.iter_mut().find(|tool| tool.name == "replace_file") {
        replace.description.push_str(
            " The controller observed this complete small file; preserve unrelated bytes in the complete atomic replacement.",
        );
    }
    true
}

fn active_unit_can_inline_completion(
    ledger: &crate::workflow::WorkUnitLedger,
    unit: &crate::workflow::WorkUnit,
) -> bool {
    let remaining = ledger
        .units
        .iter()
        .filter(|candidate| candidate.state != crate::workflow::WorkUnitState::StructurallyComplete)
        .collect::<Vec<_>>();
    remaining.len() == 1
        && remaining
            .first()
            .is_some_and(|candidate| candidate.id == unit.id)
}

fn configure_inline_completion_schema(
    tools: &mut [BuiltInToolSchema],
    inline_completion_eligible: bool,
) {
    if inline_completion_eligible {
        for tool in tools {
            if tool
                .input_schema
                .pointer("/properties/completion")
                .is_none()
            {
                continue;
            }
            let required = tool
                .input_schema
                .get_mut("required")
                .and_then(Value::as_array_mut)
                .expect("mutation schema with completion must declare required fields");
            if !required.iter().any(|field| field == "completion") {
                required.push(json!("completion"));
            }
            tool.description.push_str(
                " This is the final remaining accepted work unit: include the required completion object so the successful mutation can close implementation without another model turn.",
            );
        }
        return;
    }
    for tool in tools {
        if let Some(properties) = tool
            .input_schema
            .get_mut("properties")
            .and_then(Value::as_object_mut)
        {
            properties.remove("completion");
        }
        if let Some(required) = tool
            .input_schema
            .get_mut("required")
            .and_then(Value::as_array_mut)
        {
            required.retain(|field| field != "completion");
        }
    }
}

fn bind_work_unit_target(
    call: &mut AgentToolCall,
    active_work_unit: Option<&crate::workflow::WorkUnit>,
) -> Result<()> {
    if !matches!(
        call.tool.as_str(),
        "read_file" | "write_file" | "replace_file" | "edit_file" | "rm"
    ) {
        return Ok(());
    }
    let Some(unit) = active_work_unit else {
        return Ok(());
    };
    let arguments = call
        .arguments
        .as_object_mut()
        .context("target-bound tool arguments must be an object")?;
    arguments.insert("path".to_string(), json!(unit.path));
    Ok(())
}

fn set_mutation_target_path(tools: &mut [BuiltInToolSchema], target_path: &str) {
    for tool_name in ["write_file", "replace_file"] {
        set_tool_target_path(tools, tool_name, target_path);
    }
}

fn exposed_mutation_payload_limit(tools: &[BuiltInToolSchema]) -> Option<usize> {
    tools.iter().find_map(|tool| {
        let field = match tool.name.as_str() {
            "write_file" | "replace_file" => "content",
            "apply_patch" => "patch",
            "edit_file" => "old_text",
            _ => return None,
        };
        tool.input_schema
            .pointer(&format!("/properties/{field}/maxLength"))
            .and_then(Value::as_u64)
            .and_then(|limit| usize::try_from(limit).ok())
            .map(|limit| {
                if tool.name == "edit_file" {
                    limit * 2
                } else {
                    limit
                }
            })
    })
}

fn string_array_property(name: &'static str, description: &'static str) -> (&'static str, Value) {
    (
        name,
        json!({
            "type": "array",
            "description": description,
            "items": { "type": "string" },
        }),
    )
}

fn integer_property(name: &'static str, description: &'static str) -> (&'static str, Value) {
    (
        name,
        json!({ "type": "integer", "description": description, "minimum": 1 }),
    )
}

fn bounded_integer_property(
    name: &'static str,
    description: &'static str,
    maximum: u64,
) -> (&'static str, Value) {
    (
        name,
        json!({
            "type": "integer",
            "description": description,
            "minimum": 1,
            "maximum": maximum,
        }),
    )
}

fn enum_property<const N: usize>(
    name: &'static str,
    description: &'static str,
    values: [&'static str; N],
) -> (&'static str, Value) {
    (
        name,
        json!({ "type": "string", "description": description, "enum": values.to_vec() }),
    )
}

fn tool_allowed(
    tool: &str,
    profile: AgentProfile,
    command_backend_kind: Option<CommandBackendKind>,
    allow_sub_agents: bool,
    repository_less: bool,
) -> bool {
    if builtin_tool_semantics(tool).is_some_and(|semantics| semantics.retired) {
        return false;
    }
    if repository_less {
        return matches!(
            tool,
            "web_search" | "web_fetch" | "sub_agent" | "attachments" | "vision_describe"
        ) && (tool != "sub_agent"
            || (allow_sub_agents
                && matches!(
                    profile,
                    AgentProfile::Ask
                        | AgentProfile::Build
                        | AgentProfile::Plan
                        | AgentProfile::Monitor
                )));
    }
    match tool {
        "read_file" | "glob" | "ripgrep" | "search" | "web_search" | "web_fetch" | "git_log"
        | "session_changes" | "session_title" | "skill_search" | "skill" | "memory_search"
        | "memory_read" => true,
        "ask_user" => profile == AgentProfile::Plan,
        "memory_propose" => matches!(profile, AgentProfile::Build | AgentProfile::Plan),
        "memory_supersede" => profile == AgentProfile::Build,
        "run_command" | "run_check" => command_backend_kind.is_some(),
        "write_file" | "replace_file" | "edit_file" | "apply_patch" | "mv" | "rm" => {
            matches!(profile, AgentProfile::Build | AgentProfile::Scout)
        }
        "sub_agent" => allow_sub_agents && profile != AgentProfile::Research,
        "attachments" | "vision_describe" => true,
        _ => false,
    }
}

#[derive(Debug, Clone)]
struct StepRunOutcome {
    reached_final: bool,
    contract_status: ContractStatus,
    verified_completed: bool,
    termination_reason: TerminationReason,
    final_content: Option<String>,
    metrics: RunMetrics,
    gate_state: GateState,
}

fn incomplete_contract_status(args: &AgentRequest) -> ContractStatus {
    if args.contract.is_some() {
        ContractStatus::Unsatisfied
    } else {
        ContractStatus::Unspecified
    }
}

fn termination_reason_for_runtime_error(error: &anyhow::Error) -> TerminationReason {
    if error.downcast_ref::<ContextLimitError>().is_some() {
        return TerminationReason::ContextLimit;
    }
    let message = format!("{error:#}").to_ascii_lowercase();
    if message.contains("model invocation limit") {
        TerminationReason::InvocationLimit
    } else if message.contains("generated token limit") {
        TerminationReason::TokenLimit
    } else if message.contains("context limit") {
        TerminationReason::ContextLimit
    } else if message.contains("resource limit")
        || message.contains("resource budget")
        || message.contains("working-set limit")
        || message.contains("out of memory")
    {
        TerminationReason::ResourceLimit
    } else {
        TerminationReason::EngineError
    }
}

fn emit_context_limit_event(error: &anyhow::Error, nesting_depth: usize, sink: &mut dyn EventSink) {
    let Some(limit) = error.downcast_ref::<ContextLimitError>() else {
        return;
    };
    sink.emit(AgentEvent::ContextLimit {
        context_capacity: limit.context_capacity,
        reserved_generation_tokens: limit.reserved_generation_tokens,
        safety_margin_tokens: limit.safety_margin_tokens,
        usable_prompt_capacity: limit.usable_prompt_capacity,
        measured_prompt_tokens: limit.measured_prompt_tokens,
        largest_sections: limit
            .largest_sections
            .iter()
            .map(|(label, chars)| ContextSectionUsage {
                label: label.clone(),
                chars: *chars,
            })
            .collect(),
        nesting_depth: (nesting_depth > 0).then_some(nesting_depth),
        timestamp_ms: Some(now_millis()),
    });
}

