    #[test]
    fn workflow_terminal_tools_expose_compact_flat_artifact_schemas() {
        let tools = all_builtin_tool_specs();
        let schema = |name: &str| {
            &tools
                .iter()
                .find(|tool| tool.name == name)
                .unwrap()
                .input_schema
        };

        assert_eq!(
            schema("submit_plan")
                .pointer("/properties/steps/items/properties/paths/items/properties/change/enum")
                .unwrap(),
            &json!(["create", "modify", "delete"])
        );
        let signature = agent_tool_errors::schema_signature("submit_plan", schema("submit_plan"));
        assert!(signature.starts_with("submit_plan("));
        assert!(signature.contains("id: string"));
        assert!(signature.contains("steps: array"));
        assert_eq!(
            schema("submit_plan_review")
                .pointer("/properties/assessments/items/properties/kind/enum")
                .unwrap()
                .as_array()
                .unwrap()
                .len(),
            6
        );
        assert_eq!(
            schema("submit_plan_review").pointer("/properties/assessments/items/required"),
            Some(&json!(["kind", "status"]))
        );
        assert!(
            !schema("submit_plan_review")
                .pointer("/required")
                .unwrap()
                .as_array()
                .unwrap()
                .contains(&json!("plan_sha256"))
        );
        assert_eq!(
            schema("submit_implementation")
                .pointer("/properties/steps/items/properties/status/enum")
                .unwrap(),
            &json!(["completed", "no_change", "incomplete"])
        );
        assert_eq!(
            schema("submit_implementation").pointer("/properties/summary/maxLength"),
            Some(&json!(crate::workflow::MAX_IMPLEMENTATION_SUMMARY_CHARS))
        );
        assert_eq!(
            schema("submit_implementation")
                .pointer("/properties/steps/items/properties/summary/maxLength"),
            Some(&json!(crate::workflow::MAX_IMPLEMENTATION_SUMMARY_CHARS))
        );
        assert_eq!(
            schema("submit_implementation")
                .pointer("/properties/semantic_commit_subject/maxLength"),
            Some(&json!(crate::workflow::MAX_SEMANTIC_COMMIT_SUBJECT_CHARS))
        );
        let inline_completion = schema("edit_file")
            .pointer("/properties/completion")
            .unwrap();
        for controller_field in ["plan_id", "plan_sha256", "content_fingerprint", "no_change"] {
            assert!(
                inline_completion
                    .pointer(&format!("/properties/{controller_field}"))
                    .is_none(),
                "inline completion exposed controller-owned field {controller_field}"
            );
        }
        assert!(
            inline_completion
                .pointer("/properties/steps/items/properties/touched_paths")
                .is_none()
        );
        assert_eq!(
            inline_completion.pointer("/properties/summary/maxLength"),
            Some(&json!(crate::workflow::MAX_IMPLEMENTATION_SUMMARY_CHARS))
        );
        crate::inference::flashmoe::validate_native_tool_schema(schema("edit_file")).unwrap();
        crate::inference::flashmoe::validate_native_tool_schema(schema("submit_implementation"))
            .unwrap();
        assert_eq!(
            schema("submit_code_review")
                .pointer("/properties/assessments/items/properties/kind/enum")
                .unwrap()
                .as_array()
                .unwrap()
                .len(),
            6
        );
        assert_eq!(
            schema("submit_code_review").pointer("/properties/assessments/items/required"),
            Some(&json!(["kind", "status"]))
        );
        assert!(!PLAN_SUBMISSION_GUIDANCE.contains("\"plan\":{"));
        assert!(PLAN_SUBMISSION_GUIDANCE.contains("evaluated in step order"));
        assert!(PLAN_SUBMISSION_GUIDANCE.contains("\"check_ids\":[\"required-check-id\"]"));
        assert!(PLAN_SUBMISSION_GUIDANCE.contains("never modify or delete it before that create"));
        assert!(PLAN_REVIEW_SUBMISSION_GUIDANCE.contains("submit_plan_review"));
        assert!(IMPLEMENTATION_SUBMISSION_GUIDANCE.contains("exact current content fingerprint"));
        assert!(IMPLEMENTATION_SUBMISSION_GUIDANCE.contains("Never imitate pb's transcript"));
        assert!(
            IMPLEMENTATION_SUBMISSION_GUIDANCE
                .contains("Never call write_file for a path that already exists")
        );
        assert!(IMPLEMENTATION_SUBMISSION_GUIDANCE.contains("call read_file as one turn"));
        assert!(IMPLEMENTATION_SUBMISSION_GUIDANCE.contains("call replace_file in a later turn"));
        assert!(CODE_REVIEW_SUBMISSION_GUIDANCE.contains("submit_code_review"));
        for guidance in [
            PLAN_SUBMISSION_GUIDANCE,
            PLAN_REVIEW_SUBMISSION_GUIDANCE,
            IMPLEMENTATION_SUBMISSION_GUIDANCE,
            CODE_REVIEW_SUBMISSION_GUIDANCE,
        ] {
            assert!(guidance.contains("native function-call interface"));
            assert!(guidance.contains("compatibility action"));
            assert!(!guidance.contains("return exactly one pb tool-call JSON object"));
        }
    }

    #[test]
    fn strict_mutation_schemas_publish_the_turn_payload_allowance() {
        let mut tools = all_builtin_tool_specs();
        let limit = apply_mutation_payload_limit(&mut tools, 1_024);
        set_mutation_target_path(&mut tools, "game.js");
        assert_eq!(limit, 3_328);
        assert_eq!(compact_mutation_retry_max_tokens(1_024, limit / 2), 608);
        let schema = |name: &str| {
            &tools
                .iter()
                .find(|tool| tool.name == name)
                .unwrap()
                .input_schema
        };
        assert_eq!(
            schema("write_file").pointer("/properties/content/maxLength"),
            Some(&json!(limit))
        );
        assert_eq!(
            schema("write_file").pointer("/properties/path/enum"),
            Some(&json!(["game.js"]))
        );
        assert_eq!(
            schema("apply_patch").pointer("/properties/patch/maxLength"),
            Some(&json!(limit))
        );
        assert_eq!(
            schema("edit_file").pointer("/properties/old_text/maxLength"),
            Some(&json!(limit / 2))
        );
        assert!(
            schema("edit_file")
                .pointer("/properties/completion/properties/steps")
                .is_some()
        );
        configure_inline_completion_schema(&mut tools, true);
        let edit_schema = &tools
            .iter()
            .find(|tool| tool.name == "edit_file")
            .unwrap()
            .input_schema;
        assert!(
            edit_schema
                .pointer("/required")
                .unwrap()
                .as_array()
                .unwrap()
                .contains(&json!("completion"))
        );
        let missing_completion = agent_tool_errors::validate_arguments(
            edit_schema,
            &json!({"path": "game.js", "old_text": "old", "new_text": "new"}),
        )
        .expect("the final controller-owned mutation must reject missing completion");
        assert_eq!(
            missing_completion.reason,
            agent_tool_errors::ToolFailureReason::MissingArgument
        );
        assert!(missing_completion.message.contains("completion"));
        configure_inline_completion_schema(&mut tools, false);
        assert!(tools.iter().all(|tool| {
            tool.input_schema
                .pointer("/properties/completion")
                .is_none()
        }));
    }

