    #[test]
    fn controller_read_selects_full_small_files_and_diagnostic_ranges_only() {
        let repo = init_contract_test_repo();
        std::fs::write(repo.path().join("game.js"), "const answer = 41;\n").unwrap();
        git_run(&["add", "game.js"], repo.path()).unwrap();
        git_run(
            &["commit", "-m", "test: add controller fixture"],
            repo.path(),
        )
        .unwrap();
        let snapshot = crate::workspace::ContentSnapshot::capture(repo.path()).unwrap();
        let mut request = workflow_request(AgentProfile::Build, repo.path());
        request.workflow_stage = Some(crate::workflow::WorkflowStage::Implementing);
        request.observation_rendering = crate::workflow::ObservationRendering::ControllerBlock;
        let mut unit = crate::workflow::WorkUnit {
            id: "step:0".to_string(),
            plan_step_id: "step".to_string(),
            contributing_step_ids: Vec::new(),
            operation: crate::workflow::PlannedChange::Modify,
            path: "game.js".to_string(),
            baseline_path_fingerprint: Some(snapshot.paths["game.js"].fingerprint.clone()),
            invocation_path_fingerprint: Some(snapshot.paths["game.js"].fingerprint.clone()),
            current_path_fingerprint: Some(snapshot.paths["game.js"].fingerprint.clone()),
            adopted: false,
            state: crate::workflow::WorkUnitState::EvidenceNeeded,
        };
        let small = build_controller_read_observation(&request, &unit, repo.path(), None)
            .unwrap()
            .unwrap();
        let repeated = build_controller_read_observation(&request, &unit, repo.path(), None)
            .unwrap()
            .unwrap();
        assert_eq!(small.receipt.action_id, repeated.receipt.action_id);
        assert_eq!(
            small.receipt.coverage,
            crate::workflow::ObservationCoverage::Full
        );
        assert!(small.stage_entry.is_some());
        let expected_native_result = append_workflow_content_fingerprint(
            &request,
            "read_file",
            repo.path(),
            render_bounded_read_file("game.js", "const answer = 41;\n", 1, None, 16_000),
        )
        .unwrap();
        assert!(
            small.prompt_messages[0]
                .content
                .ends_with(&expected_native_result)
        );

        unit.operation = crate::workflow::PlannedChange::Create;
        unit.baseline_path_fingerprint = None;
        unit.invocation_path_fingerprint = None;
        unit.state = crate::workflow::WorkUnitState::DiagnosticFailed;
        let created_repair = build_controller_read_observation(
            &request,
            &unit,
            repo.path(),
            Some("error at game.js:1:1"),
        )
        .unwrap()
        .unwrap();
        assert_eq!(
            created_repair.receipt.coverage,
            crate::workflow::ObservationCoverage::Full
        );
        assert!(created_repair.stage_entry.is_some());

        let large = (1..=2_000)
            .map(|line| format!("const value_{line} = {line};"))
            .collect::<Vec<_>>()
            .join("\n");
        std::fs::write(repo.path().join("game.js"), &large).unwrap();
        let snapshot = crate::workspace::ContentSnapshot::capture(repo.path()).unwrap();
        let current = snapshot.paths["game.js"].fingerprint.clone();
        unit.current_path_fingerprint = Some(current);
        unit.operation = crate::workflow::PlannedChange::Modify;
        unit.state = crate::workflow::WorkUnitState::DiagnosticFailed;
        let ranged = build_controller_read_observation(
            &request,
            &unit,
            repo.path(),
            Some("error at game.js:1000:7"),
        )
        .unwrap()
        .unwrap();
        assert_eq!(
            ranged.receipt.coverage,
            crate::workflow::ObservationCoverage::Ranges
        );
        assert!(ranged.stage_entry.is_none());
        assert!(ranged.receipt.included_ranges[0].start_byte > 0);
        assert!(
            build_controller_read_observation(
                &request,
                &unit,
                repo.path(),
                Some("diagnostic named no exact location"),
            )
            .unwrap()
            .is_none()
        );

        unit.path = "missing.js".to_string();
        assert!(
            build_controller_read_observation(&request, &unit, repo.path(), None)
                .unwrap()
                .is_none()
        );

        unit.path = "game.js".to_string();
        unit.state = crate::workflow::WorkUnitState::EvidenceNeeded;
        std::fs::write(repo.path().join("game.js"), [0xff, 0xfe, 0xfd]).unwrap();
        assert!(
            build_controller_read_observation(&request, &unit, repo.path(), None)
                .unwrap()
                .is_none()
        );
        std::fs::write(
            repo.path().join("game.js"),
            vec![b'x'; usize::try_from(MAX_READ_FILE_BYTES.saturating_add(1)).unwrap()],
        )
        .unwrap();
        assert!(
            build_controller_read_observation(&request, &unit, repo.path(), None)
                .unwrap()
                .is_none()
        );
    }

    #[test]
    fn controller_delete_is_intrinsic_but_requires_a_current_tracked_clean_file() {
        let repo = init_contract_test_repo();
        std::fs::write(repo.path().join("game.js"), "tracked baseline\n").unwrap();
        git_run(&["add", "game.js"], repo.path()).unwrap();
        git_run(&["commit", "-m", "test: add deletion fixture"], repo.path()).unwrap();
        let snapshot = crate::workspace::ContentSnapshot::capture(repo.path()).unwrap();
        let fingerprint = snapshot.paths["game.js"].fingerprint.clone();
        let unit = crate::workflow::WorkUnit {
            id: "delete:0".to_string(),
            plan_step_id: "delete".to_string(),
            contributing_step_ids: Vec::new(),
            operation: crate::workflow::PlannedChange::Delete,
            path: "game.js".to_string(),
            baseline_path_fingerprint: Some(fingerprint.clone()),
            invocation_path_fingerprint: Some(fingerprint.clone()),
            current_path_fingerprint: Some(fingerprint),
            adopted: false,
            state: crate::workflow::WorkUnitState::EvidenceNeeded,
        };
        let mut request = workflow_request(AgentProfile::Build, repo.path());
        request.workflow_stage = Some(crate::workflow::WorkflowStage::Implementing);
        request.observation_rendering = crate::workflow::ObservationRendering::ControllerBlock;
        let gate = RefCell::new(GateState::default());
        let mut messages = Vec::new();
        let mut sink = CapturingWorkflowSink::default();

        let mut stale_unit = unit.clone();
        stale_unit.current_path_fingerprint = Some("stale".to_string());
        assert!(
            !maybe_execute_controller_delete(
                &request,
                &stale_unit,
                repo.path(),
                &gate,
                &mut messages,
                &mut sink,
            )
            .unwrap()
        );
        let mut adopted_unit = unit.clone();
        adopted_unit.adopted = true;
        assert!(
            !maybe_execute_controller_delete(
                &request,
                &adopted_unit,
                repo.path(),
                &gate,
                &mut messages,
                &mut sink,
            )
            .unwrap()
        );
        std::fs::write(repo.path().join("game.js"), "dirty local edit\n").unwrap();
        assert!(
            !maybe_execute_controller_delete(
                &request,
                &unit,
                repo.path(),
                &gate,
                &mut messages,
                &mut sink,
            )
            .unwrap()
        );
        std::fs::write(repo.path().join("game.js"), "tracked baseline\n").unwrap();

        std::fs::write(repo.path().join("untracked.js"), "not recoverable\n").unwrap();
        let untracked_snapshot = crate::workspace::ContentSnapshot::capture(repo.path()).unwrap();
        let untracked_fingerprint = untracked_snapshot.paths["untracked.js"].fingerprint.clone();
        let untracked_unit = crate::workflow::WorkUnit {
            id: "delete:untracked".to_string(),
            plan_step_id: "delete".to_string(),
            contributing_step_ids: Vec::new(),
            operation: crate::workflow::PlannedChange::Delete,
            path: "untracked.js".to_string(),
            baseline_path_fingerprint: Some(untracked_fingerprint.clone()),
            invocation_path_fingerprint: Some(untracked_fingerprint.clone()),
            current_path_fingerprint: Some(untracked_fingerprint),
            adopted: false,
            state: crate::workflow::WorkUnitState::EvidenceNeeded,
        };
        assert!(
            !maybe_execute_controller_delete(
                &request,
                &untracked_unit,
                repo.path(),
                &gate,
                &mut messages,
                &mut sink,
            )
            .unwrap()
        );
        assert!(repo.path().join("untracked.js").exists());

        std::fs::create_dir(repo.path().join("directory")).unwrap();
        let mut directory_unit = untracked_unit.clone();
        directory_unit.id = "delete:directory".to_string();
        directory_unit.path = "directory".to_string();
        assert!(
            !maybe_execute_controller_delete(
                &request,
                &directory_unit,
                repo.path(),
                &gate,
                &mut messages,
                &mut sink,
            )
            .unwrap()
        );
        assert!(repo.path().join("directory").is_dir());

        request.contract = Some(normalized_test_contract("true"));
        assert!(
            !maybe_execute_controller_delete(
                &request,
                &unit,
                repo.path(),
                &gate,
                &mut messages,
                &mut sink,
            )
            .unwrap()
        );
        request.contract.as_mut().unwrap().mutation =
            crate::harness_contract::MutationRequirement::Required;
        request.contract.as_mut().unwrap().allowed_paths = vec!["other.js".to_string()];
        assert!(
            maybe_execute_controller_delete(
                &request,
                &unit,
                repo.path(),
                &gate,
                &mut messages,
                &mut sink,
            )
            .unwrap_err()
            .to_string()
            .contains("game.js")
        );
        assert!(repo.path().join("game.js").exists());
        request.contract.as_mut().unwrap().allowed_paths = vec!["game.js".to_string()];
        assert!(
            maybe_execute_controller_delete(
                &request,
                &unit,
                repo.path(),
                &gate,
                &mut messages,
                &mut sink,
            )
            .unwrap()
        );
        assert!(!repo.path().join("game.js").exists());
        assert!(sink.events.iter().any(|event| matches!(
            event,
            AgentEvent::ControllerMutation { receipt, .. }
                if receipt.actual_origin == crate::workflow::ControllerObservationOrigin::Controller
                    && receipt.operation == crate::workflow::PlannedChange::Delete
                    && receipt.tracked
                    && !receipt.adopted
        )));
        assert!(!sink.events.iter().any(|event| matches!(
            event,
            AgentEvent::ToolCall { .. } | AgentEvent::ToolResult { .. }
        )));
        assert!(messages[0].content.contains("actual_origin=controller"));
    }

