    #[test]
    fn repair_focus_uses_exact_task_paths_named_by_failed_check_output() {
        let changed_paths = vec![
            "README.md".to_string(),
            "slugify.mjs".to_string(),
            "slugify.test.mjs".to_string(),
        ];
        let failures = vec![crate::checks::CheckFailureSummary {
            check_id: "dependency_free".to_string(),
            exit_status: 1,
            timed_out: false,
            output: "slugify.test.mjs:2: remote import\nslugify.test.mjs.backup:1: ignored"
                .to_string(),
            skip_reason: None,
        }];

        assert_eq!(
            failed_check_diagnostic_paths(&changed_paths, &failures),
            vec!["slugify.test.mjs"]
        );
        assert_eq!(
            failed_check_repair_paths(
                &["src/Component.tsx".to_string()],
                &[crate::checks::CheckFailureSummary {
                    check_id: "behavior".to_string(),
                    exit_status: 1,
                    timed_out: false,
                    output: "rendered markup did not satisfy the assertion".to_string(),
                    skip_reason: None,
                }],
                Some(&["src/Component.tsx".to_string()]),
            ),
            vec!["src/Component.tsx"]
        );
        assert!(
            failed_check_repair_paths(
                &["alpha.ts".to_string(), "beta.ts".to_string()],
                &[],
                Some(&["alpha.ts".to_string(), "beta.ts".to_string()]),
            )
            .is_empty()
        );
        assert!(!diagnostic_output_mentions_path(
            "slugify.test.mjs.backup:1",
            "slugify.test.mjs"
        ));
        assert!(diagnostic_output_mentions_path(
            "error: Expected unicode escape at file:///private/tmp/run/workspace/app.js:128:9",
            "app.js"
        ));
        assert!(!diagnostic_output_mentions_path(
            "error at file:///private/tmp/run/workspace/app.js.backup:128:9",
            "app.js"
        ));
    }

    #[test]
    fn failed_check_support_is_bounded_read_only_and_workspace_confined() {
        let repo = init_contract_test_repo();
        std::fs::create_dir_all(repo.path().join("tests")).unwrap();
        let support = repo.path().join("tests/component_test.tsx");
        std::fs::write(
            &support,
            "assert(html.includes('class=\"alert alert--error\"'));\n",
        )
        .unwrap();
        let outside = tempfile::NamedTempFile::new().unwrap();
        std::fs::write(outside.path(), "private outside evidence\n").unwrap();
        let failures = vec![crate::checks::CheckFailureSummary {
            check_id: "behavior".to_string(),
            exit_status: 1,
            timed_out: false,
            output: format!(
                "at file://{}:14:3\nat file://{}:1:1",
                support.display(),
                outside.path().display()
            ),
            skip_reason: None,
        }];

        let material = failed_check_support_material(
            repo.path(),
            &["src/Component.tsx".to_string()],
            &failures,
        );

        assert!(material.contains("tests/component_test.tsx"));
        assert!(material.contains("alert alert--error"));
        assert!(material.contains("grants no mutation, check, review, or completion evidence"));
        assert!(!material.contains("private outside evidence"));
    }

