    #[test]
    fn workflow_submission_accepts_an_exact_json_stringified_artifact() {
        let submission: Value = serde_json::from_str(&plan_submission()).unwrap();
        let expected = submission["arguments"]["plan"].clone();
        let expected_artifact: crate::workflow::PlanArtifact =
            serde_json::from_value(expected.clone()).unwrap();
        let arguments = json!({
            "id": "plan-stringified",
            "plan": expected.to_string(),
        });

        let (parsed, normalized) =
            parse_submission_artifact::<crate::workflow::PlanArtifact>(&arguments, "plan").unwrap();

        assert!(normalized);
        assert_eq!(parsed.id, "plan-stringified");
        assert_eq!(parsed.artifact, expected_artifact);

        let gate_state = RefCell::new(GateState::default());
        let result = accept_stage_artifact_submission(
            &gate_state,
            crate::workflow::StageSubmission::Plan { plan: parsed },
            "plan",
            normalized,
        )
        .unwrap();
        assert!(result.contains("parsed the JSON-stringified 'plan' artifact"));
        assert!(matches!(
            gate_state.borrow().workflow_submission,
            Some(crate::workflow::StageSubmission::Plan { .. })
        ));
    }

    #[test]
    fn compact_and_legacy_workflow_submissions_have_identical_artifact_identity() {
        let submission: Value = serde_json::from_str(&plan_submission()).unwrap();
        let artifact = submission["arguments"]["plan"].clone();
        let legacy = json!({
            "id": "plan-parity",
            "plan": artifact,
        });
        let mut compact = artifact.as_object().unwrap().clone();
        compact.insert("id".to_string(), json!("plan-parity"));

        let (legacy, legacy_normalized) =
            parse_submission_artifact::<crate::workflow::PlanArtifact>(&legacy, "plan").unwrap();
        let (compact, compact_normalized) = parse_submission_artifact::<
            crate::workflow::PlanArtifact,
        >(&Value::Object(compact), "plan")
        .unwrap();

        assert!(!legacy_normalized);
        assert!(!compact_normalized);
        assert_eq!(compact, legacy);
        assert_eq!(compact.sha256, legacy.sha256);
    }

    fn plan_review_submission(
        plan: &crate::workflow::ArtifactEnvelope<crate::workflow::PlanArtifact>,
    ) -> String {
        let assessments = crate::workflow::REQUIRED_PLAN_ASSESSMENTS
            .into_iter()
            .map(|kind| {
                json!({
                    "kind": kind,
                    "status": "pass",
                    "evidence": [],
                    "explanation": "The plan addresses this dimension."
                })
            })
            .collect::<Vec<_>>();
        json!({
            "type": "tool_call",
            "tool": "submit_plan_review",
            "arguments": {
                "id": "plan-review-1",
                "review": {
                    "plan_id": plan.id,
                    "plan_sha256": plan.sha256,
                    "assessments": assessments,
                    "challenges": [],
                    "verdict": "pass"
                }
            }
        })
        .to_string()
    }

    fn blocking_plan_review_submission(
        plan: &crate::workflow::ArtifactEnvelope<crate::workflow::PlanArtifact>,
    ) -> String {
        let assessments = crate::workflow::REQUIRED_PLAN_ASSESSMENTS
            .into_iter()
            .map(|kind| {
                json!({
                    "kind": kind,
                    "status": "concern",
                    "evidence": [],
                    "explanation": "This dimension needs revision."
                })
            })
            .collect::<Vec<_>>();
        json!({
            "type": "tool_call",
            "tool": "submit_plan_review",
            "arguments": {
                "id": "plan-review-blocking",
                "review": {
                    "plan_id": plan.id,
                    "plan_sha256": plan.sha256,
                    "assessments": assessments,
                    "challenges": [{
                        "id": "challenge-1",
                        "severity": "p1",
                        "requirement_ids": ["req-1"],
                        "description": "The implementation step needs a concrete repository path.",
                        "evidence": []
                    }],
                    "verdict": "revise"
                }
            }
        })
        .to_string()
    }

    fn delivery_plan(
        path: Option<(&str, crate::workflow::PlannedChange)>,
        check_ids: Vec<String>,
    ) -> crate::workflow::ArtifactEnvelope<crate::workflow::PlanArtifact> {
        crate::workflow::ArtifactEnvelope::new(
            "plan-delivery",
            crate::workflow::PlanArtifact {
                summary: "Make the requested delivery change".to_string(),
                requirements: vec![crate::workflow::PlanRequirement {
                    id: "req-delivery".to_string(),
                    description: "Deliver the requested repository behavior".to_string(),
                    source: "current user turn".to_string(),
                }],
                steps: vec![crate::workflow::PlanStep {
                    id: "step-delivery".to_string(),
                    requirement_ids: vec!["req-delivery".to_string()],
                    component_ids: vec!["repository".to_string()],
                    paths: path
                        .map(|(path, change)| {
                            vec![crate::workflow::PlanPath {
                                path: path.to_string(),
                                change,
                            }]
                        })
                        .unwrap_or_default(),
                    description: "Apply the bounded repository change".to_string(),
                }],
                acceptance: vec![crate::workflow::PlanAcceptance {
                    id: "accept-delivery".to_string(),
                    requirement_ids: vec!["req-delivery".to_string()],
                    check_ids,
                    description: "The harness-selected checks pass".to_string(),
                }],
                risks: Vec::new(),
                assumptions: Vec::new(),
                open_questions: Vec::new(),
                resolved_challenge_ids: Vec::new(),
            },
        )
        .unwrap()
    }

    fn plan_envelope_submission(
        plan: &crate::workflow::ArtifactEnvelope<crate::workflow::PlanArtifact>,
    ) -> String {
        json!({
            "type": "tool_call",
            "tool": "submit_plan",
            "arguments": {"id": plan.id, "plan": plan.artifact}
        })
        .to_string()
    }

    fn implementation_submission(
        plan: &crate::workflow::ArtifactEnvelope<crate::workflow::PlanArtifact>,
        content_fingerprint: &str,
        touched_paths: Vec<&str>,
        no_change: bool,
    ) -> String {
        json!({
            "type": "tool_call",
            "tool": "submit_implementation",
            "arguments": {
                "id": "implementation-delivery",
                "implementation": {
                    "plan_id": plan.id,
                    "plan_sha256": plan.sha256,
                    "content_fingerprint": content_fingerprint,
                    "steps": [{
                        "step_id": "step-delivery",
                        "status": if no_change { "no_change" } else { "completed" },
                        "touched_paths": touched_paths,
                        "summary": if no_change { "No repository change was needed" } else { "Applied the planned change" }
                    }],
                    "summary": if no_change { "The requested state already holds" } else { "Implemented the accepted plan" },
                    "no_change": no_change,
                    "semantic_commit_subject": if no_change { "" } else { "feat: deliver requested behavior" }
                }
            }
        })
        .to_string()
    }

    fn code_review_submission(
        content_fingerprint: &str,
        verdict: crate::workflow::ReviewVerdict,
        blocking_path: Option<&str>,
    ) -> String {
        let assessments = crate::workflow::REQUIRED_CODE_ASSESSMENTS
            .into_iter()
            .map(|kind| {
                json!({
                    "kind": kind,
                    "status": if verdict == crate::workflow::ReviewVerdict::Pass { "pass" } else { "concern" },
                    "evidence": [],
                    "explanation": "Reviewed this dimension against the checked bytes."
                })
            })
            .collect::<Vec<_>>();
        let findings = blocking_path
            .map(|path| {
                vec![json!({
                    "id": "finding-blocking",
                    "severity": "p1",
                    "path": path,
                    "line": 1,
                    "requirement_ids": ["req-delivery"],
                    "plan_step_ids": ["step-delivery"],
                    "evidence": [],
                    "explanation": "The first implementation does not satisfy the requested final state."
                })]
            })
            .unwrap_or_default();
        json!({
            "type": "tool_call",
            "tool": "submit_code_review",
            "arguments": {
                "id": if blocking_path.is_some() { "code-review-blocking" } else { "code-review-pass" },
                "review": {
                    "content_fingerprint": content_fingerprint,
                    "assessments": assessments,
                    "findings": findings,
                    "verdict": if verdict == crate::workflow::ReviewVerdict::Pass { "pass" } else { "revise" }
                }
            }
        })
        .to_string()
    }

    fn tool_completion(tool: &str, arguments: Value) -> ScriptedCompletion {
        ScriptedCompletion {
            content: json!({
                "type": "tool_call",
                "tool": tool,
                "arguments": arguments
            })
            .to_string(),
            truncated: false,
        }
    }

    fn text_completion(content: String) -> ScriptedCompletion {
        ScriptedCompletion {
            content,
            truncated: false,
        }
    }

    #[derive(Default)]
    struct CapturingWorkflowSink {
        events: Vec<AgentEvent>,
        checkpoints: Vec<crate::workflow::WorkflowCheckpoint>,
        cancel_requested: bool,
    }

    impl EventSink for CapturingWorkflowSink {
        fn emit(&mut self, event: AgentEvent) {
            self.events.push(event);
        }

        fn checkpoint_workflow(
            &mut self,
            checkpoint: &crate::workflow::WorkflowCheckpoint,
        ) -> Result<()> {
            checkpoint.validate()?;
            self.checkpoints.push(checkpoint.clone());
            Ok(())
        }

        fn should_cancel(&self) -> bool {
            self.cancel_requested
        }
    }

    fn run_scripted_delivery_workflow(
        request: &AgentRequest,
        workspace: &Path,
        completions: Vec<ScriptedCompletion>,
    ) -> (
        DeliveryRunOutcome,
        ScriptedCompletionEngine,
        Vec<AgentEvent>,
    ) {
        let mut generator = ScriptedCompletionEngine {
            completions: VecDeque::from(completions),
            generation_tool_counts: Vec::new(),
            generation_max_tokens: Vec::new(),
            generation_tool_names: Vec::new(),
        };
        let mcp = McpToolRegistry::default();
        let lsp = LspToolRegistry::default();
        let policy = PolicyConfig::default();
        let environment = EnvironmentConfig {
            version: crate::environment::ENVIRONMENT_CONFIG_VERSION,
            mode: EnvironmentMode::Local,
            backend: EnvironmentBackend::Local,
            image: "local".to_string(),
            init_commands: vec![],
            setup_commands: vec![],
            session_commands: vec![],
            env: BTreeMap::new(),
            bootstrap_network: EnvironmentNetworkMode::Egress,
            runtime_network: EnvironmentNetworkMode::Isolated,
            resources: Default::default(),
            caches: vec![],
            guard_commands: vec![],
            prepared_image: None,
            source: Some("explicit local test executor".to_string()),
            dockerfile: None,
        };
        let mut events = Vec::new();
        let outcome = run_delivery_workflow(
            &mut generator,
            TextBackendKind::LlamaCpp,
            None,
            request,
            workspace,
            workspace,
            None,
            Some(&environment),
            &mcp,
            &lsp,
            &policy,
            None,
            None,
            &mut |event| events.push(event),
        )
        .unwrap();
        (outcome, generator, events)
    }

    #[test]
    fn controller_observation_and_inline_completion_remove_read_and_bookkeeping_turns() {
        let repo = init_contract_test_repo();
        std::fs::write(repo.path().join("game.js"), "export const answer = 41;\n").unwrap();
        git_run(&["add", "game.js"], repo.path()).unwrap();
        git_run(
            &["commit", "-m", "test: add elision workflow fixture"],
            repo.path(),
        )
        .unwrap();
        let repository =
            crate::workspace::RepositoryContext::capture(repo.path(), repo.path()).unwrap();
        let plan = delivery_plan(
            Some(("game.js", crate::workflow::PlannedChange::Modify)),
            Vec::new(),
        );
        let reviewed_fingerprint =
            fingerprint_with_file_content(repo.path(), "game.js", "export const answer = 42;\n");
        let mut request = workflow_request(AgentProfile::Build, repo.path());
        request.ctx_size = 32_768;
        request.repository_context = Some(repository);
        request.observation_rendering = crate::workflow::ObservationRendering::ControllerBlock;
        let completion = json!({
            "id": "implementation-inline",
            "steps": [{
                "step_id": "step-delivery",
                "status": "completed",
                "summary": "Updated the exact accepted path."
            }],
            "summary": "Implemented the accepted answer update.",
            "semantic_commit_subject": "fix: correct exported answer"
        });
        let (outcome, generator, events) = run_scripted_delivery_workflow(
            &request,
            repo.path(),
            vec![
                text_completion(plan_envelope_submission(&plan)),
                text_completion(plan_review_submission(&plan)),
                tool_completion(
                    "edit_file",
                    json!({
                        "old_text": "export const answer = 41;",
                        "new_text": "export const answer = 42;",
                        "completion": completion
                    }),
                ),
                text_completion(code_review_submission(
                    &reviewed_fingerprint,
                    crate::workflow::ReviewVerdict::Pass,
                    None,
                )),
            ],
        );

        assert_eq!(
            outcome.checkpoint.run.outcome,
            Some(crate::workflow::WorkflowOutcome::Ready),
            "{}\nevents: {events:#?}",
            outcome
                .checkpoint
                .run
                .blocked_reason
                .as_deref()
                .unwrap_or("no blocked reason")
        );
        assert_eq!(generator.generation_tool_names.len(), 4);
        assert!(events.iter().any(|event| matches!(
            event,
            AgentEvent::ToolResult {
                tool,
                result,
                actor: Some(crate::events::TeamActor::Agent(AgentProfile::Build)),
                ..
            } if tool == "edit_file" && result.contains("inline_completion=accepted")
        )));
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event, AgentEvent::ControllerObservation { .. }))
                .count(),
            2
        );
        let controller_observations = events
            .iter()
            .filter_map(|event| match event {
                AgentEvent::ControllerObservation {
                    actor,
                    assisting_profile,
                    ..
                } => Some((actor, assisting_profile)),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(controller_observations.len(), 2);
        assert!(controller_observations.iter().all(|(actor, _)| matches!(
            actor,
            crate::events::TeamActor::Automation(crate::events::AutomationActor::Trinity)
        )));
        assert!(
            controller_observations
                .iter()
                .any(|(_, profile)| **profile == Some(AgentProfile::Build))
        );
        assert!(
            controller_observations
                .iter()
                .any(|(_, profile)| **profile == Some(AgentProfile::Review))
        );
        assert!(!events.iter().any(|event| matches!(
            event,
            AgentEvent::ToolCall { tool, .. }
                if matches!(tool.as_str(), "read_file" | "inspect_change" | "submit_implementation")
        )));
    }

    fn fingerprint_with_file_content(workspace: &Path, path: &str, content: &str) -> String {
        let absolute = workspace.join(path);
        let original = std::fs::read(&absolute).unwrap();
        std::fs::write(&absolute, content).unwrap();
        let fingerprint = crate::workspace::ContentSnapshot::capture(workspace)
            .unwrap()
            .fingerprint;
        std::fs::write(absolute, original).unwrap();
        fingerprint
    }

    #[test]
    fn delivery_checkpoint_resumes_exact_stage_artifacts_and_global_budget() {
        let repo = init_contract_test_repo();
        std::fs::write(repo.path().join("existing.txt"), "baseline\n").unwrap();
        git_run(&["add", "existing.txt"], repo.path()).unwrap();
        git_run(&["commit", "-m", "test: add baseline"], repo.path()).unwrap();
        let expected_fingerprint =
            fingerprint_with_file_content(repo.path(), "existing.txt", "resumed\n");
        let graph = crate::workspace::WorkspaceGraph::legacy(&["test -s existing.txt".to_string()]);
        let check_id = graph.checks.keys().next().unwrap().clone();
        let plan = delivery_plan(
            Some(("existing.txt", crate::workflow::PlannedChange::Modify)),
            vec![check_id],
        );
        let mut request = workflow_request(AgentProfile::Build, repo.path());
        request.workspace_graph = Some(graph);
        request.repository_context =
            Some(crate::workspace::RepositoryContext::capture(repo.path(), repo.path()).unwrap());
        request.turn_id = "turn-durable-resume".to_string();
        let mut first_generator = ScriptedCompletionEngine {
            completions: VecDeque::from([
                text_completion(plan_envelope_submission(&plan)),
                text_completion(plan_review_submission(&plan)),
            ]),
            generation_tool_counts: Vec::new(),
            generation_max_tokens: Vec::new(),
            generation_tool_names: Vec::new(),
        };
        let mcp = McpToolRegistry::default();
        let lsp = LspToolRegistry::default();
        let policy = PolicyConfig::default();
        let mut first_sink = CapturingWorkflowSink::default();
        let paused = run_delivery_workflow(
            &mut first_generator,
            TextBackendKind::LlamaCpp,
            None,
            &request,
            repo.path(),
            repo.path(),
            None,
            None,
            &mcp,
            &lsp,
            &policy,
            None,
            Some(crate::workflow::WorkflowStage::Implementing),
            &mut first_sink,
        )
        .unwrap();
        assert_eq!(
            paused.checkpoint.run.stage,
            crate::workflow::WorkflowStage::Implementing
        );
        assert_eq!(paused.checkpoint.run.counters.model_invocations, 2);
        assert!(first_sink.checkpoints.iter().any(|checkpoint| {
            checkpoint.run.counters.model_invocations == 1
                && checkpoint.run.counters.generated_tokens == 0
        }));
        assert!(first_sink.checkpoints.iter().any(|checkpoint| {
            checkpoint.run.counters.model_invocations == 1
                && checkpoint.run.counters.generated_tokens == 1
        }));
        assert_eq!(first_sink.checkpoints.last().unwrap(), &paused.checkpoint);

        let mut created_plan = plan.artifact.clone();
        created_plan.steps[0].paths = vec![crate::workflow::PlanPath {
            path: "created.txt".to_string(),
            change: crate::workflow::PlannedChange::Create,
        }];
        std::fs::write(repo.path().join("created.txt"), "partial resume\n").unwrap();
        let current = crate::workspace::ContentSnapshot::capture(repo.path()).unwrap();
        let planned_state =
            implementation_planned_path_state_json(&paused.checkpoint.run, &created_plan, &current)
                .unwrap();
        assert!(planned_state.contains("created_in_task_already_exists"));
        std::fs::remove_file(repo.path().join("created.txt")).unwrap();

        request.workflow_checkpoint = Some(paused.checkpoint.clone());
        let (completed, _, events) = run_scripted_delivery_workflow(
            &request,
            repo.path(),
            vec![
                tool_completion("read_file", json!({"path": "existing.txt"})),
                tool_completion(
                    "replace_file",
                    json!({"path": "existing.txt", "content": "resumed\n"}),
                ),
                text_completion(implementation_submission(
                    &plan,
                    &expected_fingerprint,
                    vec!["existing.txt"],
                    false,
                )),
                tool_completion("read_file", json!({"path": "existing.txt"})),
                text_completion(code_review_submission(
                    &expected_fingerprint,
                    crate::workflow::ReviewVerdict::Pass,
                    None,
                )),
            ],
        );

        assert_eq!(
            completed.checkpoint.run.outcome,
            Some(crate::workflow::WorkflowOutcome::Ready)
        );
        assert_eq!(completed.checkpoint.run.id, paused.checkpoint.run.id);
        assert_eq!(
            completed.checkpoint.run.counters.model_invocations, 7,
            "the resumed run must retain the two pre-restart invocations"
        );
        assert!(events.iter().any(|event| matches!(
            event,
            AgentEvent::WorkflowResumed {
                stage: crate::workflow::WorkflowStage::Implementing,
                ..
            }
        )));
    }

