    #[test]
    fn committing_resume_reconciles_a_managed_commit_completed_after_checkpoint() {
        let repo = init_contract_test_repo();
        std::fs::write(repo.path().join("existing.txt"), "baseline\n").unwrap();
        git_run(&["add", "existing.txt"], repo.path()).unwrap();
        git_run(&["commit", "-m", "test: add baseline"], repo.path()).unwrap();
        let expected_fingerprint =
            fingerprint_with_file_content(repo.path(), "existing.txt", "committed\n");
        let plan = delivery_plan(
            Some(("existing.txt", crate::workflow::PlannedChange::Modify)),
            Vec::new(),
        );
        let mut request = workflow_request(AgentProfile::Build, repo.path());
        request.repository_context =
            Some(crate::workspace::RepositoryContext::capture(repo.path(), repo.path()).unwrap());
        request.turn_id = "turn-commit-reconciliation".to_string();
        let mut generator = ScriptedCompletionEngine {
            completions: VecDeque::from([
                text_completion(plan_envelope_submission(&plan)),
                text_completion(plan_review_submission(&plan)),
                tool_completion("read_file", json!({"path": "existing.txt"})),
                tool_completion(
                    "replace_file",
                    json!({"path": "existing.txt", "content": "committed\n"}),
                ),
                text_completion(implementation_submission(
                    &plan,
                    &expected_fingerprint,
                    vec!["existing.txt"],
                    false,
                )),
                tool_completion("read_file", json!({"path": "existing.txt"})),
                text_completion(code_review_submission(
                    &expected_fingerprint,
                    crate::workflow::ReviewVerdict::Pass,
                    None,
                )),
            ]),
            generation_tool_counts: Vec::new(),
            generation_max_tokens: Vec::new(),
            generation_tool_names: Vec::new(),
        };
        let mcp = McpToolRegistry::default();
        let lsp = LspToolRegistry::default();
        let policy = PolicyConfig::default();
        let mut first_sink = CapturingWorkflowSink::default();
        let paused = run_delivery_workflow(
            &mut generator,
            TextBackendKind::LlamaCpp,
            None,
            &request,
            repo.path(),
            repo.path(),
            None,
            None,
            &mcp,
            &lsp,
            &policy,
            None,
            Some(crate::workflow::WorkflowStage::Committing),
            &mut first_sink,
        )
        .unwrap();
        assert_eq!(
            paused.checkpoint.run.stage,
            crate::workflow::WorkflowStage::Committing
        );

        let commit = managed_commit(
            &paused.checkpoint.run.repository,
            "feat: deliver requested behavior",
            None,
            &mut |_| {},
        )
        .unwrap();
        assert!(matches!(commit, ManagedCommitOutcome::Created(_)));

        request.workflow_checkpoint = Some(paused.checkpoint);
        let mut resumed_generator = ScriptedCompletionEngine {
            completions: VecDeque::new(),
            generation_tool_counts: Vec::new(),
            generation_max_tokens: Vec::new(),
            generation_tool_names: Vec::new(),
        };
        let mut resumed_sink = CapturingWorkflowSink::default();
        let resumed = run_delivery_workflow(
            &mut resumed_generator,
            TextBackendKind::LlamaCpp,
            None,
            &request,
            repo.path(),
            repo.path(),
            None,
            None,
            &mcp,
            &lsp,
            &policy,
            None,
            None,
            &mut resumed_sink,
        )
        .unwrap();

        assert_eq!(
            resumed.checkpoint.run.outcome,
            Some(crate::workflow::WorkflowOutcome::Ready)
        );
        assert!(resumed.checkpoint.run.ready_evidence.is_some());
        assert!(resumed_generator.generation_tool_names.is_empty());
        assert!(resumed_sink.events.iter().any(|event| matches!(
            event,
            AgentEvent::CommitResult {
                success: true,
                reused: true,
                ..
            }
        )));
    }

    #[test]
    fn strict_delivery_runs_plan_checks_fresh_code_review_and_managed_commit() {
        let repo = init_contract_test_repo();
        std::fs::write(repo.path().join("existing.txt"), "baseline\n").unwrap();
        git_run(&["add", "existing.txt"], repo.path()).unwrap();
        git_run(&["commit", "-m", "test: add baseline"], repo.path()).unwrap();
        std::fs::write(repo.path().join("unrelated.txt"), "preserve me\n").unwrap();
        let expected_fingerprint =
            fingerprint_with_file_content(repo.path(), "existing.txt", "delivered\n");
        let graph = crate::workspace::WorkspaceGraph::legacy(&[
            "test \"$(cat existing.txt)\" = delivered".to_string(),
        ]);
        let check_id = graph.checks.keys().next().unwrap().clone();
        let plan = delivery_plan(
            Some(("existing.txt", crate::workflow::PlannedChange::Modify)),
            vec![check_id.clone()],
        );
        let mut request = workflow_request(AgentProfile::Build, repo.path());
        let contract_check = graph.checks.get(&check_id).unwrap();
        request.contract = Some(crate::harness_contract::AgentContract {
            version: 1,
            mutation: crate::harness_contract::MutationRequirement::Required,
            allowed_paths: vec!["existing.txt".to_string()],
            work_unit_guidance: BTreeMap::new(),
            checks: vec![crate::harness_contract::AgentCheckContract {
                id: check_id.clone(),
                command: contract_check.command.clone(),
                cwd: contract_check.cwd.clone(),
                required: true,
                diagnostic_eligible: false,
                timeout_seconds: contract_check.timeout_seconds,
            }],
            commit: crate::harness_contract::HarnessCommitContract {
                required: true,
                semantic: true,
            },
            review: crate::harness_contract::HarnessReviewContract {
                required: true,
                read_paths: vec!["existing.txt".to_string()],
                check_ids: vec![check_id.clone()],
            },
            workspace_clean: false,
        });
        request.workspace_graph = Some(graph);
        request.repository_context =
            Some(crate::workspace::RepositoryContext::capture(repo.path(), repo.path()).unwrap());
        request.turn_id = "turn-strict-happy".to_string();

        let (outcome, generator, events) = run_scripted_delivery_workflow(
            &request,
            repo.path(),
            vec![
                text_completion(plan_envelope_submission(&plan)),
                text_completion(plan_review_submission(&plan)),
                tool_completion("read_file", json!({"path": "existing.txt"})),
                tool_completion(
                    "replace_file",
                    json!({"path": "existing.txt", "content": "delivered\n"}),
                ),
                text_completion(implementation_submission(
                    &plan,
                    &expected_fingerprint,
                    vec!["existing.txt"],
                    false,
                )),
                tool_completion("read_file", json!({"path": "existing.txt"})),
                text_completion(code_review_submission(
                    &expected_fingerprint,
                    crate::workflow::ReviewVerdict::Pass,
                    None,
                )),
            ],
        );

        assert_eq!(
            outcome.checkpoint.run.outcome,
            Some(crate::workflow::WorkflowOutcome::Ready),
            "{}\nevents: {:#?}",
            outcome
                .checkpoint
                .run
                .blocked_reason
                .as_deref()
                .unwrap_or("no blocked reason"),
            events
        );
        assert_eq!(outcome.step.contract_status, ContractStatus::Satisfied);
        assert!(outcome.step.verified_completed);
        assert_eq!(
            outcome.checkpoint.run.selected_checks,
            vec![check_id.clone()]
        );
        assert!(outcome.checkpoint.run.commit.is_some());
        let ready_evidence = outcome.checkpoint.run.ready_evidence.as_ref().unwrap();
        assert_eq!(
            ready_evidence.commit_oid,
            outcome.checkpoint.run.commit.as_ref().unwrap().oid
        );
        assert_eq!(
            ready_evidence.plan_sha256,
            outcome.checkpoint.run.plan.as_ref().unwrap().sha256
        );
        assert_eq!(
            ready_evidence.review_sha256,
            outcome.checkpoint.run.code_review.as_ref().unwrap().sha256
        );
        assert_eq!(
            ready_evidence.check_evidence_ids,
            vec![format!("check:{check_id}")]
        );
        assert!(ready_evidence.repository_remote.is_none());
        let ready_evidence_sha256 = ready_evidence.sha256().unwrap();
        assert!(generator.completions.is_empty());
        assert_eq!(
            git_run(&["log", "-1", "--pretty=%s"], repo.path())
                .unwrap()
                .trim(),
            "feat: deliver requested behavior"
        );
        assert_eq!(
            git_run(&["show", "--pretty=", "--name-only", "HEAD"], repo.path())
                .unwrap()
                .trim(),
            "existing.txt"
        );
        assert_eq!(
            std::fs::read_to_string(repo.path().join("unrelated.txt")).unwrap(),
            "preserve me\n"
        );
        let started = events
            .iter()
            .filter_map(|event| match event {
                AgentEvent::WorkflowStageStarted { stage, .. } => Some(*stage),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(
            started,
            vec![
                crate::workflow::WorkflowStage::Planning,
                crate::workflow::WorkflowStage::PlanReview,
                crate::workflow::WorkflowStage::Implementing,
                crate::workflow::WorkflowStage::Checking,
                crate::workflow::WorkflowStage::CodeReview,
                crate::workflow::WorkflowStage::Committing,
            ]
        );
        assert!(events.iter().any(|event| matches!(
            event,
            AgentEvent::WorkflowCompleted {
                outcome: crate::workflow::WorkflowOutcome::Ready,
                ready_evidence_sha256: Some(actual),
                ..
            } if actual == &ready_evidence_sha256
        )));
    }

    #[test]
    fn strict_delivery_verification_requires_an_explicit_satisfied_contract() {
        assert_eq!(
            delivery_contract_projection(crate::workflow::WorkflowOutcome::Ready, false),
            (ContractStatus::Unspecified, false)
        );
        assert_eq!(
            delivery_contract_projection(crate::workflow::WorkflowOutcome::NoChange, false),
            (ContractStatus::Unspecified, false)
        );
        assert_eq!(
            delivery_contract_projection(crate::workflow::WorkflowOutcome::Ready, true),
            (ContractStatus::Satisfied, true)
        );
        assert_eq!(
            delivery_contract_projection(crate::workflow::WorkflowOutcome::NoChange, true),
            (ContractStatus::Satisfied, true)
        );
        assert_eq!(
            delivery_contract_projection(crate::workflow::WorkflowOutcome::ChecksFailed, true),
            (ContractStatus::Unsatisfied, false)
        );
    }

    #[test]
    fn strict_no_change_stops_after_harness_checks_without_review_or_commit() {
        let repo = init_contract_test_repo();
        let baseline = crate::workspace::ContentSnapshot::capture(repo.path()).unwrap();
        let plan = delivery_plan(None, Vec::new());
        let mut request = workflow_request(AgentProfile::Build, repo.path());
        request.repository_context =
            Some(crate::workspace::RepositoryContext::capture(repo.path(), repo.path()).unwrap());
        request.turn_id = "turn-strict-no-change".to_string();
        let head_before = git_run(&["rev-parse", "HEAD"], repo.path()).unwrap();

        let (outcome, generator, events) = run_scripted_delivery_workflow(
            &request,
            repo.path(),
            vec![
                text_completion(plan_envelope_submission(&plan)),
                text_completion(plan_review_submission(&plan)),
                text_completion(implementation_submission(
                    &plan,
                    &baseline.fingerprint,
                    Vec::new(),
                    true,
                )),
            ],
        );

        assert_eq!(
            outcome.checkpoint.run.outcome,
            Some(crate::workflow::WorkflowOutcome::NoChange)
        );
        assert!(!outcome.step.verified_completed);
        assert!(outcome.checkpoint.run.code_review.is_none());
        assert!(outcome.checkpoint.run.commit.is_none());
        assert!(outcome.checkpoint.run.ready_evidence.is_none());
        assert!(events.iter().any(|event| matches!(
            event,
            AgentEvent::WorkflowCompleted {
                outcome: crate::workflow::WorkflowOutcome::NoChange,
                ready_evidence_sha256: None,
                ..
            }
        )));
        assert!(generator.completions.is_empty());
        assert_eq!(
            git_run(&["rev-parse", "HEAD"], repo.path()).unwrap(),
            head_before
        );
        assert!(!events.iter().any(|event| matches!(
            event,
            AgentEvent::WorkflowStageStarted {
                stage: crate::workflow::WorkflowStage::CodeReview,
                ..
            }
        )));
    }

