    #[test]
    fn stage_tool_surfaces_follow_capabilities_not_persona() {
        let repo = init_contract_test_repo();
        let request = workflow_request(AgentProfile::Ask, repo.path());
        let limits = request.workflow_policy.as_ref().unwrap().limits;
        let plan = crate::workflow::StageContract::strict(
            crate::workflow::WorkflowStage::Planning,
            limits,
            512,
        )
        .unwrap();
        let plan_outcome = run_scripted_stage(
            &request,
            &plan,
            stage_context(),
            vec![ScriptedCompletion {
                content: plan_submission(),
                truncated: false,
            }],
            repo.path(),
            &mut |_| {},
        )
        .unwrap();
        let plan_tools = &plan_outcome.generation_tool_names[0];
        assert!(plan_tools.contains(&"submit_plan".to_string()));
        assert!(plan_tools.contains(&"read_file".to_string()));
        assert!(!plan_tools.contains(&"run_command".to_string()));
        assert!(!plan_tools.contains(&"write_file".to_string()));
        assert!(!plan_tools.contains(&"git_commit".to_string()));

        let mut narrowed_request = request.clone();
        narrowed_request.workflow_tool_exclusions = vec!["read_file".to_string()];
        let narrowed_plan_outcome = run_scripted_stage(
            &narrowed_request,
            &plan,
            stage_context(),
            vec![ScriptedCompletion {
                content: plan_submission(),
                truncated: false,
            }],
            repo.path(),
            &mut |_| {},
        )
        .unwrap();
        let narrowed_tools = &narrowed_plan_outcome.generation_tool_names[0];
        assert!(!narrowed_tools.contains(&"read_file".to_string()));
        assert!(narrowed_tools.contains(&"submit_plan".to_string()));

        let mut invalid_request = request.clone();
        invalid_request.workflow_tool_exclusions = vec!["submit_plan".to_string()];
        let error = run_scripted_stage(
            &invalid_request,
            &plan,
            stage_context(),
            vec![ScriptedCompletion {
                content: plan_submission(),
                truncated: false,
            }],
            repo.path(),
            &mut |_| {},
        )
        .unwrap_err()
        .to_string();
        assert!(error.contains("cannot remove terminal tool 'submit_plan'"));

        let implementation = crate::workflow::StageContract::strict(
            crate::workflow::WorkflowStage::Implementing,
            limits,
            512,
        )
        .unwrap();
        let implementation_outcome = run_scripted_stage(
            &request,
            &implementation,
            stage_context(),
            vec![ScriptedCompletion {
                content: json!({
                    "type":"tool_call",
                    "tool":"request_replan",
                    "arguments":{"reason":"A material dependency changed"}
                })
                .to_string(),
                truncated: false,
            }],
            repo.path(),
            &mut |_| {},
        )
        .unwrap();
        let implementation_tools = &implementation_outcome.generation_tool_names[0];
        for expected in [
            "run_command",
            "run_task",
            "run_check",
            "write_file",
            "submit_implementation",
            "request_replan",
        ] {
            assert!(implementation_tools.contains(&expected.to_string()));
        }
        assert!(!implementation_tools.contains(&"git_commit".to_string()));
        assert!(!implementation_tools.contains(&"todo".to_string()));
    }

    #[test]
    fn se1_closure_exposure_is_an_authorized_allowlisted_subset_for_every_target_stage() {
        for (stage, terminal_tool) in [
            (crate::workflow::WorkflowStage::Planning, "submit_plan"),
            (crate::workflow::WorkflowStage::PlanRevision, "submit_plan"),
            (
                crate::workflow::WorkflowStage::PlanReview,
                "submit_plan_review",
            ),
            (
                crate::workflow::WorkflowStage::CodeReview,
                "submit_code_review",
            ),
        ] {
            let capabilities = crate::workflow::StageCapabilities::for_stage(stage);
            let authorized = all_builtin_tool_specs()
                .into_iter()
                .filter(|tool| capabilities.allows_tool(&tool.name))
                .collect::<Vec<_>>();
            assert!(authorized.iter().any(|tool| tool.name == terminal_tool));

            for ordinary_steps_remaining in [1, 2] {
                for terminal_ready in [false, true] {
                    let exposure = ToolExposureState::for_turn(
                        Some(stage),
                        ordinary_steps_remaining,
                        Some(terminal_tool),
                        terminal_ready,
                    );
                    let exposed = authorized
                        .iter()
                        .filter(|tool| exposure.allows(&tool.name))
                        .collect::<Vec<_>>();
                    assert!(
                        exposed
                            .iter()
                            .all(|tool| capabilities.allows_tool(&tool.name))
                    );
                    if !terminal_ready {
                        assert!(exposed.iter().all(|tool| tool.name != terminal_tool));
                    }
                    if terminal_ready && ordinary_steps_remaining == 1 {
                        assert_eq!(
                            exposed
                                .iter()
                                .map(|tool| tool.name.as_str())
                                .collect::<Vec<_>>(),
                            vec![terminal_tool]
                        );
                    }

                    let request_allowlist = ["read_file", terminal_tool];
                    let allowlisted = exposed
                        .iter()
                        .filter(|tool| request_allowlist.contains(&tool.name.as_str()))
                        .collect::<Vec<_>>();
                    assert!(
                        allowlisted
                            .iter()
                            .all(|tool| request_allowlist.contains(&tool.name.as_str()))
                    );
                    assert!(
                        allowlisted
                            .iter()
                            .all(|tool| capabilities.allows_tool(&tool.name))
                    );
                }
            }
        }

        for stage in [
            crate::workflow::WorkflowStage::Implementing,
            crate::workflow::WorkflowStage::Repairing,
        ] {
            let exposure =
                ToolExposureState::for_turn(Some(stage), 1, Some("submit_implementation"), true);
            assert!(exposure.allows("submit_implementation"));
            assert!(!exposure.allows("run_check"));
            assert!(!exposure.allows("write_file"));
        }
    }

