    #[test]
    fn capped_native_action_signature_tracks_real_progress_state() {
        let before = ProgressState {
            workspace_fingerprint: "workspace-a".to_string(),
            evidence_fingerprint: "evidence-a".to_string(),
        };
        let after = ProgressState {
            workspace_fingerprint: "workspace-b".to_string(),
            evidence_fingerprint: "evidence-a".to_string(),
        };
        let first = "one\n<｜DSML｜invoke name=\"write_file\">";
        let second = "different prose\n<｜DSML｜invoke name=\"write_file\">";

        assert_eq!(
            parse_failure_signature(
                first,
                "first parser detail",
                CompletionFinishReason::MaxTokens,
                &before,
            ),
            parse_failure_signature(
                second,
                "different parser detail",
                CompletionFinishReason::MaxTokens,
                &before,
            )
        );
        assert_ne!(
            parse_failure_signature(
                first,
                "first parser detail",
                CompletionFinishReason::MaxTokens,
                &before,
            ),
            parse_failure_signature(
                first,
                "first parser detail",
                CompletionFinishReason::MaxTokens,
                &after,
            )
        );
    }

    #[test]
    fn detects_a_truncated_native_mutation_tool_and_target() {
        let output = concat!(
            "<tool_call>\n<function=todo>\n<parameter=op>complete\n</tool_call>\n",
            "<tool_call>\n<function=write_file>\n<parameter=path>game.js\n<parameter=content>partial"
        );

        assert_eq!(truncated_native_tool_name(output), Some("write_file"));
        assert_eq!(
            truncated_native_mutation_path(output).as_deref(),
            Some("game.js")
        );
        let qwen = "<tool_call>{\"name\":\"replace_file\",\"arguments\":{\"path\":\"src/game.js\",\"content\":\"partial";
        assert_eq!(
            truncated_native_mutation_path(qwen).as_deref(),
            Some("src/game.js")
        );
        let escaped_parameter = concat!(
            "<tool_call><function=write_file><parameter=content>partial",
            "<parameter=path>app.test.mjs\\n  }\\n}"
        );
        assert_eq!(
            truncated_native_mutation_path(escaped_parameter).as_deref(),
            Some("app.test.mjs")
        );
    }

