    #[test]
    fn available_tool_specs_filter_by_profile_and_backend() {
        let review_tools = available_tool_specs(
            AgentProfile::Review,
            None,
            false,
            false,
            &McpToolRegistry::default(),
            &LspToolRegistry::default(),
        );
        assert!(review_tools.iter().any(|tool| tool.name == "read_file"));
        assert!(
            !review_tools
                .iter()
                .any(|tool| tool.name == "inspect_change")
        );
        assert!(!review_tools.iter().any(|tool| tool.name == "edit_file"));
        assert!(!review_tools.iter().any(|tool| tool.name == "run_command"));

        let build_tools = available_tool_specs(
            AgentProfile::Build,
            Some(CommandBackendKind::Local),
            true,
            false,
            &McpToolRegistry::default(),
            &LspToolRegistry::default(),
        );
        let run_command = build_tools
            .iter()
            .find(|tool| tool.name == "run_command")
            .expect("run_command should be available with a backend");
        assert!(!build_tools.iter().any(|tool| tool.name == "inspect_change"));
        assert_eq!(run_command.input_schema["type"], "object");
        assert_eq!(run_command.input_schema["required"], json!(["cmd"]));
        let replace_file = build_tools
            .iter()
            .find(|tool| tool.name == "replace_file")
            .expect("replace_file should be available to build profiles");
        assert_eq!(
            replace_file.input_schema["required"],
            json!(["path", "content"])
        );
        assert!(build_tools.iter().any(|tool| tool.name == "sub_agent"));
        assert!(
            !build_tools
                .iter()
                .any(|tool| tool.name.starts_with("browser_") || tool.name.starts_with("react_"))
        );
        let sub_agent = build_tools
            .iter()
            .find(|tool| tool.name == "sub_agent")
            .unwrap();
        let targets = sub_agent.input_schema["properties"]["profile"]["enum"]
            .as_array()
            .unwrap();
        assert!(!targets.contains(&json!("build")));
        assert!(!targets.contains(&json!("scout")));
    }

